/* Cubic interpolation between b and c using neighbours a and d at parameter t. */
float cubic_hermite_scalar(float a, float b, float c, float d, float t) {
    float p = (d - c) - (a - b);
    float q = (a - b) - p;
    float t2 = t * t;
    float t3 = t2 * t;
    return p * t3 + q * t2 + (c - a) * t + b;
}

