        if (!entry)
            return 0;
        if (*(short *)(entry + 2))
            moby_joints_to_scratchpad(entity, *(short *)(entry + 2), 0);
        if (*(int *)(entry + 4) <= 0)
            return 0;
        count = 0;
        index = 0;
        total = 0.0f;
        entry += 0x10;
