                            sceVu0ScaleVector(((Moby *)entity)->scale * 0.0009765625f, &second,
                                              (void *)(0x70000000 + (*(short *)(list + 2) << 4)));
                            FastVecSub(&third, &first, &second);
                            radius = FastVecLength(&third);
                            extent = *(float *)(list + 8) * ((Moby *)entity)->scale * 0.0009765625f;
