    unsigned int y = truncate_float_to_s32(g * 255.0f) & 0xFF;
    unsigned int z = truncate_float_to_s32(b * 255.0f) & 0xFF;
    unsigned int w = truncate_float_to_s32(a * 255.0f);
    return x | (y << 8) | (z << 16) | (w << 24);
