/* Swaps the three channel values in pairs selected by the mask bits. */
void swap_color_channel_words(int *a, int *b, int *c, int mask) {
    int x, y;
    if (mask & 1) {
        x = *b;
        y = *a;
        *a = x;
        *b = y;
    }
    if (mask & 2) {
        x = *c;
        y = *b;
        *b = x;
        *c = y;
    }
    if (mask & 4) {
        x = *a;
        y = *c;
        *c = x;
        *a = y;
    }
}
