// Advances an index with wrapping or directional clamping.
int offset_path_index(int *limit, int index, int delta, int wrap) {
    if (wrap)
        index = (index + delta + *limit) % *limit;
    else {
        index += delta;
        if (delta < 0) {
            if (index < 0)
                index = 0;
        } else {
            if (index > *limit - 1)
                index = *limit - 1;
        }
    }
    return index;
}
