f32 normalize_angle(f32 a) {
    f32 out;
    f32 x;
    f32 pi = 3.14159274f;
    f32 tp = 6.2831855f;

    x = a + pi;
    x /= tp;
    x = split_float_fraction(&out, x);
    x *= tp;
    return x - pi;
}
