    unsigned char *pa = &item_available[id];
    unsigned char *pb = &items_acquired[id];
    int idx = id + 0x25;
    int *p;
    int i;

    if (*pa == 0) {
        idx = id;
    }
    p = &item_pickup_banner_ids[idx];
    *pb = 1;
    if (*p != -1) {
        queue_dialogue_message(*p, scale_ticks(0x12C));
    }
    if (*pa == 0) {
        ItemRec *r;
        *pa = 1;
        r = &item_price_table[id];
        *pb = 1;
        if (r->a != 0) {
            int *q = &weapon_ammo_counts[id];
            int v = r->b;
            if (v < *q) {
                v = *q;
            }
            *q = v;
        }
        for (i = 0; i < 20; i++) {
            if (id != 0 && level_item_ids[i] == id) {
                int j;
                for (j = 0;; j++) {
                    unsigned char b = vendor_stock[j];
                    if ((b & 0x3F) == id || b == 0xFF) {
                        vendor_stock[j] = id | 0x40;
                        break;
                    }
                }
                break;
            }
        }
        if (flag != 0) {
            int t = item_defs[id].t;
            if (t == 0) {
                *(int *)(g_hero_field_20a5 + 0x13) = id;
            } else if (t == 3) {
                *(int *)(g_hero_field_20a5 + 0x1F) = id;
            } else if (t == 2) {
                *(int *)(g_hero_field_20a5 + 0x1B) = id;
            }
        }
        if (item_defs[id].t == 0) {
            for (i = 0; i < 8 && pause_iop_sprite_lists[i] != 0; i++) {
            }
            if (i < 8) {
                pause_iop_sprite_lists[i] = id;
            }
        }
    }
